<?php require_once __DIR__.'/includes/bootstrap.php'; $pageTitle='Census & Statistics'; $search=trim($_GET['q']??'');$purok=trim($_GET['purok']??''); $residents=(int)value($pdo,'SELECT COUNT(*) FROM residents');$families=(int)value($pdo,'SELECT COUNT(*) FROM family');$zones=rows($pdo,'SELECT purok,COUNT(DISTINCT id) households,0 residents FROM families WHERE (:p="" OR purok=:p) GROUP BY purok',['p'=>$purok]); if(!$zones)$zones=rows($pdo,'SELECT "Published aggregate data" purok,COUNT(*) households,COUNT(*) residents FROM family'); $age=rows($pdo,"SELECT CASE WHEN TIMESTAMPDIFF(YEAR,Date_of_Birth,CURDATE())<15 THEN '0-14' WHEN TIMESTAMPDIFF(YEAR,Date_of_Birth,CURDATE())<25 THEN '15-24' WHEN TIMESTAMPDIFF(YEAR,Date_of_Birth,CURDATE())<45 THEN '25-44' WHEN TIMESTAMPDIFF(YEAR,Date_of_Birth,CURDATE())<60 THEN '45-59' ELSE '60+' END bracket,COUNT(*) total FROM residents GROUP BY bracket ORDER BY FIELD(bracket,'0-14','15-24','25-44','45-59','60+')");$senior=(int)value($pdo,"SELECT COUNT(*) FROM residents WHERE TIMESTAMPDIFF(YEAR,Date_of_Birth,CURDATE())>=60");require __DIR__.'/includes/header.php';?><main><a class="back" href="dashboard.php"><i class="fa-solid fa-arrow-left"></i> Explore information / Census & Statistics</a><section class="hero"><i class="fa-solid fa-chart-simple"></i><div><h1>Census & Statistics</h1><p>Understand our population and household information.</p></div></section><section class="section"><div class="stats"><div class="stat"><strong><?= $residents ?></strong><span>Total residents</span></div><div class="stat"><strong><?= $families ?></strong><span>Total families</span></div><div class="stat"><strong><?= count($zones) ?></strong><span>Puroks / zones</span></div><div class="stat"><strong><?= $senior ?></strong><span>Senior citizens</span></div></div></section><section class="section"><article class="panel"><form class="form-grid" method="get"><div><label for="q">Search data</label><input id="q" name="q" value="<?= h($search) ?>" placeholder="Search purok or age bracket"></div><div><label for="purok">Purok / zone</label><input id="purok" name="purok" value="<?= h($purok) ?>" placeholder="Purok 2"></div><div class="full"><button class="button" type="submit">Filter statistics</button></div></form></article></section><section class="section grid two"><article class="panel"><h2>Population by age</h2><canvas id="age-chart"></canvas></article><article class="panel"><h2>Households by purok</h2><canvas id="purok-chart"></canvas></article></section><section class="section"><article class="panel"><h2>Purok breakdown</h2><table><thead><tr><th>Purok / zone</th><th>Households</th><th>Residents</th><th>Avg. household size</th></tr></thead><tbody><?php if(!$zones):?><tr><td colspan="4" class="empty">No aggregate data published yet.</td></tr><?php else:foreach($zones as $z):?><tr><td><?= h($z['purok']) ?></td><td><?= (int)$z['households'] ?></td><td><?= (int)$z['residents'] ?></td><td><?= $z['households']?(int)round($z['residents']/$z['households'],1):0 ?></td></tr><?php endforeach;endif;?></tbody></table><div class="actions"><a class="button" href="census-export.php?<?= http_build_query(['purok'=>$purok]) ?>"><i class="fa-solid fa-download"></i> Download PDF</a><form method="post" action="save-item.php"><input type="hidden" name="csrf_token" value="<?= csrf() ?>"><input type="hidden" name="type" value="census"><input type="hidden" name="return" value="census-statistics.php"><button class="button alt" type="submit" data-requires-login data-authenticated="<?= logged_in()?'1':'0' ?>" data-intent="save these statistics">Save</button></form><button class="button alt" type="button" data-requires-login data-authenticated="<?= logged_in()?'1':'0' ?>" data-intent="share these statistics" onclick="navigator.share?navigator.share({title:'Census & Statistics',url:location.href}):alert('Copy this page link to share it.')">Share</button></div></article></section></main><script src="https://cdn.jsdelivr.net/npm/chart.js"></script><script>new Chart(document.getElementById('age-chart'),{type:'bar',data:{labels:<?= json_encode(array_column($age,'bracket')) ?>,datasets:[{label:'Residents',data:<?= json_encode(array_map('intval',array_column($age,'total'))) ?>,backgroundColor:'#157567'}]}});new Chart(document.getElementById('purok-chart'),{type:'doughnut',data:{labels:<?= json_encode(array_column($zones,'purok')) ?>,datasets:[{data:<?= json_encode(array_map('intval',array_column($zones,'households'))) ?>,backgroundColor:['#157567','#e8a33d','#0f3a44','#8ac5b4']}]}});</script><?php require __DIR__.'/includes/login-gate-modal.php';require __DIR__.'/includes/footer.php';?>
